 using Contoso.Text;

 namespace Contoso.Text.Tests;

 [TestClass]
 public sealed class StringFormatterTests
 {
     private readonly StringFormatter _formatter = new();

     // --- FormatPhoneNumber ---

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_StartsWithAreaCodeInParentheses()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.StartsWith("(555)", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_EndsWithLastFourDigits()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.EndsWith("4567", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_MatchesExpectedFormat()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.MatchesRegex(@"^\(\d{3}\) \d{3}-\d{4}$", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ReturnsCorrectValue()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.AreEqual("(555) 123-4567", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_NullInput_ThrowsArgumentNullException()
     {
         var ex = Assert.ThrowsExactly<ArgumentNullException>(
             () => _formatter.FormatPhoneNumber(null!));

         Assert.AreEqual("digits", ex.ParamName);
     }

     [TestMethod]
     [DataRow("123", DisplayName = "Too short")]
     [DataRow("12345678901", DisplayName = "Too long")]
     [DataRow("", DisplayName = "Empty")]
     public void FormatPhoneNumber_InvalidLength_ThrowsArgumentException(string digits)
     {
         var ex = Assert.ThrowsExactly<ArgumentException>(
             () => _formatter.FormatPhoneNumber(digits));

         Assert.AreEqual("digits", ex.ParamName);
         Assert.Contains("10 digits", ex.Message);
     }

     // --- BuildGreeting ---

     [TestMethod]
     public void BuildGreeting_WithDefaultTitle_StartsWithDearMr()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.StartsWith("Dear Mr.", result);
     }

     [TestMethod]
     public void BuildGreeting_WithDefaultTitle_EndsWithNameAndComma()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.EndsWith("Smith,", result);
     }

     [TestMethod]
     public void BuildGreeting_WithCustomTitle_ContainsTitle()
     {
         var result = _formatter.BuildGreeting("Johnson", "Dr.");

         Assert.Contains("Dr.", result);
         Assert.StartsWith("Dear Dr.", result);
     }

     [TestMethod]
     public void BuildGreeting_WithCustomTitle_ReturnsCorrectValue()
     {
         var result = _formatter.BuildGreeting("Johnson", "Dr.");

         Assert.AreEqual("Dear Dr. Johnson,", result);
     }

     [TestMethod]
     [DataRow(null)]
     [DataRow("")]
     [DataRow("   ")]
     public void BuildGreeting_NullOrWhitespaceName_Throws(string? name)
     {
         Assert.Throws<ArgumentException>(
             () => _formatter.BuildGreeting(name!));
     }

     // --- GenerateSlug ---

     [TestMethod]
     public void GenerateSlug_SimpleTitle_ReturnsLowercaseHyphenated()
     {
         var result = _formatter.GenerateSlug("Hello World");

         Assert.AreEqual("hello-world", result);
         Assert.MatchesRegex(@"^[a-z0-9\-]+$", result);
     }

     [TestMethod]
     public void GenerateSlug_TitleWithSpecialChars_ContainsOnlySlugChars()
     {
         var result = _formatter.GenerateSlug("C# is Great!!!");

         Assert.MatchesRegex(@"^[a-z0-9]+(-[a-z0-9]+)*$", result);
     }

     [TestMethod]
     public void GenerateSlug_TitleWithLeadingTrailingSpaces_DoesNotStartOrEndWithHyphen()
     {
         var result = _formatter.GenerateSlug("  Padded Title  ");

         Assert.StartsWith("p", result);
         Assert.EndsWith("e", result);
         Assert.AreEqual("padded-title", result);
     }

     [TestMethod]
     [DataRow("My Blog Post", "my-blog-post")]
     [DataRow("  Spaces  Everywhere  ", "spaces-everywhere")]
     [DataRow("ALL CAPS TITLE", "all-caps-title")]
     [DataRow("dots.and" + "/slashes", "dots-and-slashes")]
     public void GenerateSlug_VariousInputs_ReturnsExpected(string title, string expected)
     {
         var result = _formatter.GenerateSlug(title);

         Assert.AreEqual(expected, result);
     }

     [TestMethod]
     [DataRow(null)]
     [DataRow("")]
     [DataRow("   ")]
     public void GenerateSlug_NullOrWhitespace_Throws(string? title)
     {
         Assert.Throws<ArgumentException>(
             () => _formatter.GenerateSlug(title!));
     }

     // --- FormatCurrency ---

     [TestMethod]
     public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
     {
         var result = _formatter.FormatCurrency(19.99m);

         Assert.StartsWith("$", result);
     }

     [TestMethod]
     public void FormatCurrency_CustomSymbol_StartsWithSymbol()
     {
         var result = _formatter.FormatCurrency(42.50m, "€");

         Assert.StartsWith("€", result);
     }

     [TestMethod]
     public void FormatCurrency_WholeNumber_EndsWithTwoDecimalPlaces()
     {
         var result = _formatter.FormatCurrency(100m);

         Assert.EndsWith(".00", result);
     }

     [TestMethod]
     public void FormatCurrency_NegativeAmount_ContainsMinusSign()
     {
         var result = _formatter.FormatCurrency(-5.50m);

         Assert.Contains("-", result);
         Assert.AreEqual("$-5.50", result);
     }

     [TestMethod]
     [DataRow("19.99", "$", "$19.99")]
     [DataRow("0.00", "$", "$0.00")]
     [DataRow("1234.56", "£", "£1234.56")]
     [DataRow("100", "¥", "¥100.00")]
     public void FormatCurrency_VariousInputs_ReturnsExpected(
         string amount, string symbol, string expected)
     {
         var result = _formatter.FormatCurrency(decimal.Parse(amount), symbol);

         Assert.AreEqual(expected, result);
     }

     [TestMethod]
     public void FormatCurrency_Amount_MatchesCurrencyPattern()
     {
         var result = _formatter.FormatCurrency(9.90m, "$");

         Assert.MatchesRegex(@"^\$\d+\.\d{2}$", result);
     }
